const tabs=['bench','microgrid','projects','study','tutoring'] as const;
type CampusTab=typeof tabs[number];
const tabNames={bench:T('Bancada virtual','Virtual bench','Banco virtual'),microgrid:T('Microrrede 24 h','24-hour microgrid','Microrred 24 h'),projects:T('Projetos e manutenção','Projects and maintenance','Proyectos y mantenimiento'),study:T('Estudar offline','Study offline','Estudiar sin conexión'),tutoring:T('Turma e tutoria','Class and tutoring','Clase y tutoría')};
const caseNames={school:T('Escola ribeirinha','Riverside school','Escuela ribereña'),community:T('Centro comunitário','Community centre','Centro comunitario'),rain:T('Escola • dia pouco ensolarado','School • low-sun day','Escuela • día de poco sol')};
function useLocale(){const{t,lang}=useApp();return{t,lang,q:(pt:string,en:string,es:string)=>t(T(pt,en,es)),n:(v:number,d=2)=>format(v,lang,d)};}
function Num({label,value,onChange,min,max,step=1,unit=''}:{label:Localized;value:number;onChange:(v:number)=>void;min:number;max:number;step?:number;unit?:string}){
 const{t,q}=useLocale();const[draft,setDraft]=useState(String(value));useEffect(()=>setDraft(String(value)),[value]);const x=Number(draft),invalid=draft===''||!Number.isFinite(x)||x<min||x>max||(step===1&&!Number.isInteger(x));
 return <label className={`am-number ${invalid?'invalid':''}`}><span>{t(label)}</span><div><input type="number" aria-label={t(label)} value={draft} min={min} max={max} step={step} aria-invalid={invalid} onChange={e=>{setDraft(e.target.value);const v=Number(e.target.value);if(e.target.value!==''&&Number.isFinite(v)&&v>=min&&v<=max&&(step!==1||Number.isInteger(v)))onChange(v);}}/><small>{unit}</small></div>{invalid&&<small role="alert">{q('Fora do intervalo. Resultado usa o último valor válido.','Out of range. Results use the last valid value.','Fuera de rango. El resultado usa el último valor válido.')}</small>}</label>;
}
function Metric({label,value,unit,accent=false}:{label:Localized;value:string;unit?:string;accent?:boolean}){const{t}=useLocale();return <div className={`am-metric ${accent?'accent':''}`}><span>{t(label)}</span><strong>{value}<small>{unit}</small></strong></div>;}
function Note({children,warning=false}:{children:ReactNode;warning?:boolean}){return <div className={`am-note ${warning?'warning':''}`}><Icon name={warning?'shield':'info'}/><div>{children}</div></div>;}
const feedback:Record<string,Localized>={
 ready:T('Conexões completas no modelo. Faça uma medição e registre a relação entre causa e resultado.','Model connections complete. Take a measurement and record cause and result.','Conexiones completas en el modelo. Mide y registra causa y resultado.'),
 open:T('Há um circuito aberto. Confira os oito enlaces da referência e a falha selecionada.','Open circuit. Check the eight reference links and the selected fault.','Circuito abierto. Comprueba los ocho enlaces y el fallo seleccionado.'),
 short:T('Curto virtual detectado. A proteção idealizada interrompe a saída; o modelo não estima corrente real de curto ou energia de arco.','Virtual short circuit detected. Idealized protection disconnects the output; actual short-circuit current and arc energy are not calculated.','Cortocircuito virtual detectado. La protección idealizada interrumpe la salida; no se calcula corriente real de cortocircuito ni energía de arco.'),
 reverse:T('Polaridade invertida. A saída foi bloqueada no modelo. Revise os terminais + e −.','Reverse polarity. Model output is blocked. Review + and − terminals.','Polaridad invertida. La salida está bloqueada. Revisa los terminales + y −.'),
 wiring:T('Existe uma ligação fora da topologia proposta. Revise as entradas do controlador, a bateria e a separação CC/CA.','A connection is outside the proposed topology. Review controller inputs, battery and DC/AC separation.','Hay una conexión fuera de la topología propuesta. Revisa entradas del controlador, batería y separación CC/CA.'),
 fuse:T('Proteção aberta no ensaio. Compare as leituras antes e depois de restaurar a condição normal.','Protection is open in this experiment. Compare readings before and after restoring normal operation.','Protección abierta en el ensayo. Compara lecturas antes y después de restablecer la condición normal.'),
 pvVoltage:T('Voc acima de 150 V: limite hipotético do controlador ultrapassado. Reduza os módulos em série; use sempre os limites da ficha técnica em um projeto real.','Voc exceeds the illustrative 150 V controller limit. Reduce series modules; real design requires actual datasheet limits.','Voc supera el límite hipotético de 150 V del controlador. Reduce módulos en serie; un diseño real requiere los límites de la ficha técnica.'),
 pvLow:T('Tensão de entrada insuficiente para o controlador buck modelado. A fonte não carrega a bateria nesta condição.','Input voltage is too low for the modeled buck controller. The source does not charge the battery in this condition.','Tensión de entrada insuficiente para el controlador buck modelado. La fuente no carga la batería en esta condición.'),
 overload:T('Carga acima da potência nominal suposta do inversor. A saída foi interrompida no ensaio.','Load exceeds the assumed inverter rating. Output is disconnected in this experiment.','La carga supera la potencia nominal supuesta del inversor. La salida se interrumpe en este ensayo.'),
 drop:T('Queda de tensão acima da meta didática de 3% neste trecho CC. Compare comprimento, corrente e seção; isso não verifica capacidade de condução ou conformidade normativa.','Voltage drop exceeds this exercise’s 3% DC target. Compare length, current and section; ampacity and regulatory compliance are not checked.','La caída supera la meta didáctica del 3% en este tramo CC. Compara longitud, corriente y sección; no se verifica capacidad de corriente ni conformidad normativa.'),
 controllerLimit:T('O controlador atingiu o limite de corrente de carga configurado. Parte da potência disponível não será transferida.','The controller reached its configured charging-current limit. Some available power is not transferred.','El controlador alcanzó el límite configurado de corriente de carga. Parte de la potencia disponible no se transfiere.'),
 socLow:T('SOC no piso de 20% da bancada. A descarga adicional é bloqueada e a carga depende da fonte.','SOC reached the bench’s 20% floor. Further discharge is blocked and the load depends on the source.','SOC en el mínimo del 20% del banco. Se bloquea la descarga adicional y la carga depende de la fuente.')
};
const portPositions:Record<Terminal,[number,number]>={'source+':[70,158],'source-':[145,158],'mpptPV+':[280,158],'mpptPV-':[355,158],'mpptBAT+':[280,242],'mpptBAT-':[355,242],'bat+':[480,355],'bat-':[555,355],'invDC+':[680,158],'invDC-':[755,158],invL:[680,242],invN:[755,242],loadL:[880,355],loadN:[955,355]};
function BenchBoard({result}:{result:BenchResult}){
 const{q,n}=useLocale(),{record,patch}=useLearning();const[selected,setSelected]=useState<Terminal|null>(null);
 const connect=(id:Terminal)=>{if(!selected){setSelected(id);return;}if(id===selected){setSelected(null);return;}const exists=record.wires.some(w=>w.includes(id)&&w.includes(selected));if(!exists&&record.wires.length<24)patch({wires:[...record.wires,[selected,id]]});setSelected(null);};
 const device=(left:number,top:number,width:number,icon:string,title:string,value:string,caption:string)=><div className="am-device" style={{left,top,width}}><Icon name={icon}/><strong>{title}</strong><b>{value}</b><small>{caption}</small></div>;
 return <><div className="am-board-toolbar"><div><span className="eyebrow">{q('CONEXÕES INTERATIVAS','INTERACTIVE CONNECTIONS','CONEXIONES INTERACTIVAS')}</span><p>{selected?q(`Terminal ${selected} selecionado. Toque no destino.`,`Terminal ${selected} selected. Tap its destination.`,`Terminal ${selected} seleccionado. Toca el destino.`):q('Toque em dois terminais para criar um fio. Remova enlaces na lista abaixo.','Tap two terminals to create a wire. Remove links in the list below.','Toca dos terminales para crear un cable. Elimina enlaces en la lista inferior.')}</p></div><div className="am-actions"><Button icon="layers" onClick={()=>{patch({wires:referenceWires.map(w=>[...w]),fault:'none'});setSelected(null);}}>{q('Montagem de referência','Reference wiring','Montaje de referencia')}</Button><Button icon="reset" onClick={()=>{patch({wires:[]});setSelected(null);}}>{q('Limpar fios','Clear wires','Borrar cables')}</Button></div></div>
 <div className="am-board-scroll" tabIndex={0} aria-label={q('Bancada; deslize horizontalmente para ver os componentes','Bench; scroll horizontally to see components','Banco; desplaza horizontalmente para ver componentes')}><div className="am-board"><svg className="am-wires" viewBox="0 0 1020 410" aria-hidden="true"><defs><pattern id="am-grid" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="currentColor" opacity=".14"/></pattern></defs><rect width="1020" height="410" fill="url(#am-grid)"/>{record.wires.map(([a,b],i)=>{const[x1,y1]=portPositions[a],[x2,y2]=portPositions[b];const color=a.endsWith('-')||a.endsWith('N')?'var(--blue)':'var(--accent)';return <path key={i} d={`M${x1},${y1} C${x1},${y1+60} ${x2},${y2+60} ${x2},${y2}`} stroke={color} strokeWidth="2.5" fill="none" opacity=".8"/>;})}</svg>
 {device(25,30,165,record.bench.source==='solar'?'sun':'wind',record.bench.source==='solar'?q('Arranjo FV','PV array','Arreglo FV'):q('Eólico + retificador','Wind + rectifier','Eólico + rectificador'),n(result.sourceW/1000)+' kW',q('Modelo de fonte CC','DC source model','Modelo de fuente CC'))}
 {device(250,30,160,'layers',q('Controlador híbrido','Hybrid controller','Controlador híbrido'),n(result.controllerW/1000)+' kW','PV ≤ 150 V • η 96%')}
 {device(450,228,155,'bolt',q('Banco de baterias','Battery bank','Banco de baterías'),n(result.batteryV,1)+' V',`SOC ${n(record.bench.soc,0)}% • ${n(record.bench.batteryV*record.bench.batteryAh/1000,1)} kWh`)}
 {device(650,30,170,'waves',q('Inversor','Inverter','Inversor'),n(result.outputW/1000)+' kW','CC → 220 V CA • 60 Hz')}
 {device(845,228,150,'plant',q('Carga equivalente','Equivalent load','Carga equivalente'),n(result.outputA,2)+' A',q('Resistiva • FP = 1','Resistive • PF = 1','Resistiva • FP = 1'))}
 {terminalIds.map(id=>{const[x,y]=portPositions[id];return <button key={id} className={`am-port ${selected===id?'selected':''}`} style={{left:x-18,top:y-18}} aria-label={`${q('Terminal','Terminal','Terminal')} ${id}`} aria-pressed={selected===id} onClick={()=>connect(id)}><span>{id.endsWith('+')?'+':id.endsWith('-')?'−':id.endsWith('L')?'L':'N'}</span><small>{id.replace('source',record.bench.source==='solar'?'FV':'EOL')}</small></button>;})}
 </div></div><div className="am-wire-list">{record.wires.map(([a,b],i)=><button key={i} onClick={()=>patch({wires:record.wires.filter((_,index)=>index!==i)})} aria-label={`${q('Remover fio','Remove wire','Eliminar cable')} ${a} → ${b}`}><span>{a} → {b}</span><Icon name="close"/></button>)}{!record.wires.length&&<p>{q('Nenhum fio conectado. Comece pela fonte e pelo controlador.','No wires connected. Start with the source and controller.','Sin cables conectados. Empieza por la fuente y el controlador.')}</p>}</div></>;
}
function Instrument({result:r}:{result:BenchResult}){
 const{q,n}=useLocale();const[mode,setMode]=useState<'dc'|'ac'|'clamp'|'scope'|'iv'>('dc'),[a,setA]=useState<Terminal>('source+'),[b,setB]=useState<Terminal>('source-'),[branch,setBranch]=useState('source');
 const options={dc:q('V CC','V DC','V CC'),ac:q('V CA','V AC','V CA'),clamp:q('Alicate virtual','Virtual clamp meter','Pinza virtual'),scope:q('Osciloscópio','Oscilloscope','Osciloscopio'),iv:q('Curva I–V','I–V curve','Curva I–V')};
 const meter=measureVoltage(r,a,b,mode==='ac'?'ac':'dc'),amps=branch==='source'?r.drawI:branch==='battery'?r.batteryW/r.batteryV:r.outputA;
 const maxI=Math.max(.1,r.sourceIsc),maxV=Math.max(1,r.sourceVoc),ivPath=r.curve.map((p,i)=>`${i?'L':'M'}${48+p.v/maxV*570},${190-p.i/maxI*150}`).join(' ');
 return <section className="panel am-instrument"><div className="panel-heading"><div><span className="eyebrow">{q('INSTRUMENTAÇÃO VIRTUAL','VIRTUAL INSTRUMENTATION','INSTRUMENTACIÓN VIRTUAL')}</span><h2>{q('Meça antes de concluir.','Measure before concluding.','Mide antes de concluir.')}</h2></div><Icon name="waves"/></div><div className="am-small-tabs" role="group" aria-label={q('Instrumento','Instrument','Instrumento')}>{Object.entries(options).map(([key,title])=><button key={key} aria-pressed={mode===key} className={mode===key?'selected':''} onClick={()=>{setMode(key as typeof mode);if(key==='ac'){setA('invL');setB('invN');}if(key==='dc'){setA('source+');setB('source-');}}}>{title}</button>)}</div>
 {(mode==='dc'||mode==='ac')&&<><div className="am-probes"><label>{q('Ponta A','Probe A','Punta A')}<select value={a} onChange={e=>setA(e.target.value as Terminal)}>{terminalIds.map(id=><option key={id}>{id}</option>)}</select></label><label>{q('Ponta B','Probe B','Punta B')}<select value={b} onChange={e=>setB(e.target.value as Terminal)}>{terminalIds.map(id=><option key={id}>{id}</option>)}</select></label></div><div className="am-display" role="status"><small>{options[mode]} {mode==='ac'?'RMS':''}</small><strong>{meter.reason==='ok'&&meter.value!==null?n(meter.value):'—'}<span>V</span></strong><p>{meter.reason==='domain'?q('Selecione terminais do domínio CC ou CA correspondente.','Select terminals in the matching DC or AC domain.','Selecciona terminales del dominio CC o CA correspondiente.'):meter.reason==='floating'?q('Potencial indefinido nesta topologia.','Potential is undefined in this topology.','Potencial indefinido en esta topología.'):q('Leitura calculada pelo modelo. Inverta as pontas em CC e observe o sinal.','Model-calculated reading. Swap DC probes and observe the sign.','Lectura calculada por el modelo. Invierte las puntas CC y observa el signo.')}</p></div></>}
 {mode==='clamp'&&<><label className="am-select">{q('Trecho medido','Measured branch','Tramo medido')}<select value={branch} onChange={e=>setBranch(e.target.value)}><option value="source">{q('Fonte CC','DC source','Fuente CC')}</option><option value="battery">{q('Bateria CC (+ carga / − descarga)','Battery DC (+ charge / − discharge)','Batería CC (+ carga / − descarga)')}</option><option value="load">{q('Carga CA','AC load','Carga CA')}</option></select></label><div className="am-display"><small>{options.clamp}</small><strong>{n(amps)}<span>A</span></strong><p>{q('Instrumento virtual sem inserção em série no circuito.','Virtual instrument without series insertion in the circuit.','Instrumento virtual sin inserción en serie en el circuito.')}</p></div></>}
 {mode==='scope'&&<><svg viewBox="0 0 660 230" role="img" aria-label={q('Senoide ideal de tensão de saída em dois ciclos','Ideal output-voltage sine wave over two cycles','Senoide ideal de tensión de salida durante dos ciclos')} className="am-plot"><path className="am-axis" d="M45 25V200H625 M45 113H625"/><path className="am-plot-line" d={Array.from({length:241},(_,i)=>`${i?'L':'M'}${45+i/240*580},${113-Math.sin(i/240*4*Math.PI)*(r.outputV?78:0)}`).join(' ')}/><text x="50" y="17">{n(r.outputV*Math.SQRT2,1)} V pico</text><text x="45" y="220">0 ms</text><text x="570" y="220">33,33 ms</text></svg><p>{q('Senoide ideal de 60 Hz. Não calcula harmônicos, chaveamento PWM ou transitórios de partida.','Ideal 60 Hz sine wave. Harmonics, PWM switching and starting transients are not modeled.','Senoide ideal de 60 Hz. No calcula armónicos, conmutación PWM ni transitorios de arranque.')}</p></>}
 {mode==='iv'&&<><svg viewBox="0 0 660 230" className="am-plot" role="img" aria-label={q('Curva corrente versus tensão aproximada da fonte CC','Approximate DC-source current versus voltage curve','Curva aproximada corriente-tensión de la fuente CC')}><path className="am-axis" d="M48 25V190H620"/><path className="am-plot-line" d={ivPath}/><circle cx={48+r.sourceV/maxV*570} cy={190-r.sourceI/maxI*150} r="5" fill="var(--accent)"/><text x="8" y="22">I (A)</text><text x="575" y="220">V (V)</text><text x="48" y="211">0</text><text x="570" y="211">{n(r.sourceVoc,1)}</text></svg><p>{q('Aproximação linear por três pontos: Isc, ponto de operação e Voc. Não é curva medida ou modelo de diodo. Na fonte eólica, representa apenas a saída CC ilustrativa.','Three-point linear approximation: Isc, operating point and Voc. Not a measured curve or diode model. For wind, it represents only the illustrative DC output.','Aproximación lineal de tres puntos: Isc, punto de operación y Voc. No es una curva medida ni modelo de diodo. En eólica representa solo la salida CC ilustrativa.')}</p></>}
 <div className="am-analyzer"><span>P = {n(r.outputW/1000)} kW</span><span>S = {n(r.outputVA/1000)} kVA</span><span>FP = 1</span><span>f nominal = 60 Hz</span></div></section>;
}
function Bench(){const{q,t,n}=useLocale(),{record,patch}=useLearning();const p=record.bench,r=useMemo(()=>evaluateBench(p,record.wires,record.fault),[p,record.wires,record.fault]);const set=(key:keyof BenchInput,value:number|BenchInput['source'])=>patch({bench:{...p,[key]:value}});const field=(key:Exclude<keyof BenchInput,'source'>,label:Localized,unit='',step=1)=><Num key={key} label={label} value={p[key]} min={benchRanges[key][0]} max={benchRanges[key][1]} step={step} unit={unit} onChange={value=>set(key,value)}/>;
 return <><div className="am-metrics"><Metric accent label={T('Potência disponível na fonte','Available source power','Potencia disponible en fuente')} value={n(r.sourceW/1000)} unit="kW"/><Metric label={T('Potência entregue à carga','Power delivered to load','Potencia entregada a la carga')} value={n(r.outputW/1000)} unit="kW"/><Metric label={T('Queda CC no ponto de referência','DC drop at reference point','Caída CC en punto de referencia')} value={n(r.dropPct)} unit="%"/><Metric label={T('Tensão da bateria','Battery voltage','Tensión de batería')} value={n(r.batteryV,1)} unit="V"/></div>
 <section className="panel am-bench"><BenchBoard result={r}/><div className="am-bench-bottom"><label className="am-select">{q('Falha simulada','Simulated fault','Fallo simulado')}<select value={record.fault} onChange={e=>patch({fault:e.target.value as BenchFault})}>{[['none',q('Sem falha inserida','No inserted fault','Sin fallo añadido')],['open',q('Circuito aberto','Open circuit','Circuito abierto')],['reverse',q('Polaridade invertida','Reverse polarity','Polaridad invertida')],['short',q('Curto virtual','Virtual short circuit','Cortocircuito virtual')],['fuse',q('Proteção aberta','Open protection','Protección abierta')],['overload',q('Sobrecarga ×4','Overload ×4','Sobrecarga ×4')]].map(([key,name])=><option value={key} key={key}>{name}</option>)}</select></label><Button icon="clock" onClick={()=>set('soc',Math.round(r.socAfter10min*10)/10)}>{q('Avançar 10 min','Advance 10 min','Avanzar 10 min')}</Button><small>{q('O passo usa potências constantes e atualiza o SOC.','The step uses constant power and updates SOC.','El paso usa potencia constante y actualiza el SOC.')}</small></div></section>
 <div className="am-two-col"><section className="panel am-panel"><div className="panel-heading"><h2>{q('Parâmetros da bancada','Bench parameters','Parámetros del banco')}</h2><button className="reset-button" onClick={()=>patch({bench:{...benchDefaults},wires:referenceWires.map(w=>[...w]),fault:'none'})}>{q('Restaurar','Reset','Restablecer')}</button></div><label className="am-select">{q('Fonte primária','Primary source','Fuente primaria')}<select value={p.source} onChange={e=>set('source',e.target.value as BenchInput['source'])}><option value="solar">{q('Solar fotovoltaica','Solar PV','Solar fotovoltaica')}</option><option value="wind">{q('Eólica retificada (modelo)','Rectified wind (model)','Eólica rectificada (modelo)')}</option></select></label><div className="am-field-grid">{p.source==='solar'?<>{field('series',T('Módulos em série','Series modules','Módulos en serie'))}{field('parallel',T('Strings em paralelo','Parallel strings','Cadenas en paralelo'))}{field('irradiance',T('Irradiância','Irradiance','Irradiancia'),'W/m²')}{field('cellTemp',T('Temperatura das células','Cell temperature','Temperatura de células'),'°C')}</>:<>{field('windSpeed',T('Velocidade do vento','Wind speed','Velocidad del viento'),'m/s',.1)}{field('rotorDiameter',T('Diâmetro do rotor','Rotor diameter','Diámetro del rotor'),'m',.1)}</>}{field('length',T('Cabo: comprimento de ida','Cable: one-way length','Cable: longitud de ida'),'m')}{field('section',T('Seção de cobre (hipótese)','Copper section (assumption)','Sección de cobre (hipótesis)'),'mm²',.5)}{field('cableTemp',T('Temperatura do condutor','Conductor temperature','Temperatura del conductor'),'°C')}{field('soc',T('Estado de carga (SOC)','State of charge (SOC)','Estado de carga (SOC)'),'%')}{field('batteryAh',T('Capacidade nominal da bateria','Battery nominal capacity','Capacidad nominal de batería'),'Ah')}{field('loadW',T('Potência ativa da carga','Active load power','Potencia activa de carga'),'W')}{field('inverterW',T('Potência nominal do inversor','Inverter rating','Potencia nominal del inversor'),'W')}{field('controllerA',T('Limite de carga do controlador','Controller charging limit','Límite de carga del controlador'),'A')}</div><p className="am-caption">{q('Módulo hipotético: 550 Wp, Vmp 41 V, Voc 49,5 V, Isc 14,3 A em STC. Bateria genérica de 48 V; tensão versus SOC ilustrativa. Não representa ficha de fabricante.','Hypothetical module: 550 Wp, Vmp 41 V, Voc 49.5 V, Isc 14.3 A at STC. Generic 48 V battery; illustrative voltage-SOC relation. Not a manufacturer datasheet.','Módulo hipotético: 550 Wp, Vmp 41 V, Voc 49,5 V, Isc 14,3 A en STC. Batería genérica de 48 V; relación tensión-SOC ilustrativa. No representa ficha de fabricante.')}</p></section><div><Instrument result={r}/><section className="panel am-panel am-feedback"><h2>{q('Feedback do ensaio','Experiment feedback','Retroalimentación del ensayo')}</h2><ul>{r.codes.map(code=><li key={code} className={code==='ready'?'good':r.tripped?'bad':'warn'}><Icon name={code==='ready'?'check':'info'}/><span>{t(feedback[code])}</span></li>)}</ul></section></div></div>
 <details className="panel am-details"><summary>{q('Fórmulas e limites do modelo','Model formulas and limits','Fórmulas y límites del modelo')}</summary><div className="am-formulas"><code>Pfv = Ns × Np × 550 × (G/1000) × [1 − 0,0035(Tc − 25)]</code><code>Peol = ½ × 1,225 × π(D/2)² × v³ × 0,35 × 0,90</code><code>Rida+volta = 2 × ρ20 × [1 + 0,00393(Tcabo − 20)] × L / S</code><code>ΔV = I × R • Pcabo = I²R • ΔV% = 100 × ΔV / V</code><code>ρ20 = 0,0175 Ω·mm²/m • ηcontrolador = 0,96 • ηinversor = 0,92</code></div><p>{q('Trecho de cabo calculado: fonte → controlador. Não calcula ampacidade, proteção, aterramento, arco, química da bateria, sombreamento parcial ou transitórios. Cores dos fios apenas didáticas. Falhas existem somente no ambiente virtual.','Calculated cable branch: source → controller. Ampacity, protection design, grounding, arcs, battery chemistry, partial shading and transients are not modeled. Wire colors are educational. Faults exist only in the virtual environment.','Tramo de cable calculado: fuente → controlador. No calcula capacidad de corriente, protecciones, puesta a tierra, arco, química de batería, sombreado parcial ni transitorios. Los colores son didácticos. Los fallos existen solo en el entorno virtual.')}</p></details></>;
}
function HybridChart({r}:{r:HybridResult}){const{q,n}=useLocale();const max=Math.max(.5,...r.rows.flatMap(x=>[x.load,x.pv,x.diesel]));const line=(key:'load'|'pv'|'diesel')=>r.rows.map((row,i)=>`${i?'L':'M'}${45+i/23*610},${205-row[key]/max*170}`).join(' ');return <div className="am-charts"><svg viewBox="0 0 700 245" className="am-plot" role="img" aria-label={q('Potências médias horárias de carga, solar e diesel','Hourly mean load, solar and diesel power','Potencias medias horarias de carga, solar y diésel')}><path className="am-axis" d="M45 25V205H660"/>{[.25,.5,.75,1].map(f=><g key={f}><path d={`M45 ${205-170*f}H660`} stroke="var(--line)" strokeDasharray="3 5"/><text x="2" y={210-170*f}>{n(max*f,1)}</text></g>)}<path d={line('load')} stroke="var(--ink)" fill="none" strokeWidth="2"/><path d={line('pv')} stroke="var(--accent)" fill="none" strokeWidth="3"/><path d={line('diesel')} stroke="var(--warning)" fill="none" strokeWidth="2"/>{[0,6,12,18,23].map(h=><text key={h} x={45+h/23*610} y="228" textAnchor="middle">{h} h</text>)}<text x="10" y="15">kW</text></svg><div className="am-legend"><span className="load">{q('Carga','Load','Carga')}</span><span className="solar">Solar</span><span className="diesel">Diesel</span></div><svg viewBox="0 0 700 120" className="am-soc-plot" role="img" aria-label={q('Estado de carga da bateria hora a hora','Hourly battery state of charge','Estado de carga de batería por hora')}><path className="am-axis" d="M45 12V85H660"/><path d={r.rows.map((row,i)=>`${i?'L':'M'}${45+i/23*610},${85-row.soc*.65}`).join(' ')} stroke="var(--blue)" fill="none" strokeWidth="2.5"/><text x="0" y="20">SOC %</text><text x="48" y="105">0 h</text><text x="610" y="105">23 h</text></svg></div>;}
function LoadEditor(){const{q}=useLocale(),{record,patch}=useLearning();const change=(id:string,field:keyof LoadRow,value:string|number)=>patch({loads:record.loads.map(row=>row.id===id?{...row,[field]:value}:row)});return <section className="panel am-panel"><div className="panel-heading"><div><span className="eyebrow">{q('INVENTÁRIO DE CARGAS','LOAD INVENTORY','INVENTARIO DE CARGAS')}</span><h2>{q('O consumo começa pelos equipamentos.','Demand starts with the equipment.','El consumo empieza por los equipos.')}</h2></div><Button icon="layers" disabled={record.loads.length>=30} onClick={()=>patch({loads:[...record.loads,{id:'load-'+Date.now().toString(36),label:q('Nova carga','New load','Nueva carga'),watts:100,quantity:1,start:8,end:17,duty:1}]})}>{q('Adicionar carga','Add load','Añadir carga')}</Button></div><div className="am-table-scroll"><table className="am-loads"><thead><tr>{[q('Equipamento','Equipment','Equipo'),'W',q('Quantidade','Quantity','Cantidad'),q('Início (h)','Start (h)','Inicio (h)'),q('Fim (h)','End (h)','Fin (h)'),q('Uso médio (%)','Mean duty (%)','Uso medio (%)'),''].map((x,i)=><th key={i}>{x}</th>)}</tr></thead><tbody>{record.loads.map(row=><tr key={row.id}><td><input aria-label={q('Nome da carga','Load name','Nombre de carga')} value={row.label} maxLength={100} onChange={e=>change(row.id,'label',e.target.value)}/></td>{([['watts',0,20000,1,'W'],['quantity',1,100,1,''],['start',0,23,1,'h'],['end',0,24,1,'h'],['duty',0,100,1,'%']] as const).map(([key,min,max,step,unit])=><td key={key}><Num label={`${row.label} • ${key}`} value={key==='duty'?row.duty*100:row[key]} min={min} max={max} step={step} unit={unit} onChange={v=>change(row.id,key,key==='duty'?v/100:v)}/></td>)}<td><button className="icon-button" aria-label={q(`Excluir ${row.label}`,`Delete ${row.label}`,`Eliminar ${row.label}`)} onClick={()=>patch({loads:record.loads.filter(x=>x.id!==row.id)})}><Icon name="trash"/></button></td></tr>)}</tbody></table></div><p className="am-caption">{q('Potência ativa média. Início maior que fim representa uso noturno. 0 → 24 cobre o dia inteiro; início = fim desliga a carga. Uso médio representa um ciclo idealizado. Partidas e simultaneidade abaixo de uma hora não são simuladas.','Mean active power. Start later than end represents overnight use. 0 → 24 covers the full day; equal start and end switches the load off. Duty is idealized. Starting transients and sub-hour simultaneity are not simulated.','Potencia activa media. Inicio mayor que fin representa uso nocturno. 0 → 24 cubre todo el día; inicio = fin apaga la carga. El uso medio es idealizado. No se simulan arranques ni simultaneidad inferior a una hora.')}</p></section>;}
function Microgrid(){const{q,n,t}=useLocale(),{record,patch}=useLearning(),p=record.hybrid,r=useMemo(()=>dispatchHybrid(p,record.loads),[p,record.loads]);const set=(key:keyof HybridInput,value:number|HybridInput['strategy'])=>patch({hybrid:{...p,[key]:value}});const field=(key:Exclude<keyof HybridInput,'strategy'>,label:Localized,unit='',step=.1)=>{const[min,max]=hybridRanges[key];return <Num key={key} label={label} value={p[key]} min={key==='socStart'?p.socMin:min} max={key==='socStart'?p.socMax:max} unit={unit} step={step} onChange={v=>set(key,v)}/>;};
 const apply=(key:keyof typeof casePresets)=>{const c=casePresets[key];patch({caseId:key,hybrid:{...c.input},loads:c.loads.map(row=>({...row}))});};
 return <><div className="am-case-strip"><div><small>{q('CENÁRIO HIPOTÉTICO','HYPOTHETICAL CASE','ESCENARIO HIPOTÉTICO')}</small><strong>{t(caseNames[record.caseId])}</strong></div><div className="am-actions">{Object.keys(caseNames).map(key=><button className={record.caseId===key?'selected':''} key={key} onClick={()=>apply(key as keyof typeof casePresets)}>{t(caseNames[key as keyof typeof caseNames])}</button>)}</div></div>
 <div className="am-metrics"><Metric accent label={T('Demanda diária','Daily demand','Demanda diaria')} value={n(r.loadKWh)} unit="kWh"/><Metric label={T('Combustível utilizado','Fuel consumed','Combustible utilizado')} value={n(r.dieselLiters)} unit="L"/><Metric label={T('Energia não atendida','Unserved energy','Energía no atendida')} value={n(r.unservedKWh)} unit="kWh"/><Metric label={T('SOC ao fim do dia','End-of-day SOC','SOC al final del día')} value={n(r.socFinal,1)} unit="%"/></div>
 <div className="am-two-col"><section className="panel am-panel"><div className="panel-heading"><h2>{q('Geração e armazenamento','Generation and storage','Generación y almacenamiento')}</h2></div><div className="am-field-grid">{field('pvKWp',T('Arranjo fotovoltaico','PV array','Arreglo fotovoltaico'),'kWp')}{field('sunHours',T('Horas de sol pleno (HSP)','Peak sun hours','Horas solares pico'),'h/dia')}{field('batteryKWh',T('Armazenamento nominal','Nominal storage','Almacenamiento nominal'),'kWh')}{field('socStart',T('SOC inicial','Initial SOC','SOC inicial'),'% ',1)}{field('inverterKW',T('Limite do inversor','Inverter limit','Límite del inversor'),'kW')}{field('batteryKW',T('Limite de potência da bateria','Battery power limit','Límite de potencia de batería'),'kW')}{field('generatorKW',T('Gerador a diesel','Diesel generator','Generador diésel'),'kW')}{field('fuelLiters',T('Diesel disponível no dia','Diesel available for the day','Diésel disponible en el día'),'L')}</div><label className="am-select">{q('Estratégia de despacho','Dispatch strategy','Estrategia de despacho')}<select value={p.strategy} onChange={e=>set('strategy',e.target.value as HybridInput['strategy'])}><option value="battery-first">{q('Solar → bateria → diesel','Solar → battery → diesel','Solar → batería → diésel')}</option><option value="reserve">{q('Preservar reserva de bateria','Preserve battery reserve','Preservar reserva de batería')}</option></select></label>{p.strategy==='reserve'&&field('reserveSOC',T('Reserva desejada de SOC','SOC reserve target','Reserva deseada de SOC'),'% ',1)}<details className="am-subdetails"><summary>{q('Hipóteses de eficiência e diesel','Efficiency and diesel assumptions','Hipótesis de eficiencia y diésel')}</summary><div className="am-field-grid">{field('performance',T('Fator global FV','PV performance factor','Factor global FV'),'',.01)}{field('etaCharge',T('Rendimento de carga','Charging efficiency','Eficiencia de carga'),'',.01)}{field('etaDischarge',T('Rendimento de descarga','Discharge efficiency','Eficiencia de descarga'),'',.01)}{field('generatorMin',T('Carga mínima do diesel (fração)','Diesel minimum load (fraction)','Carga mínima diésel (fracción)'),'',.01)}{field('fuelIdle',T('Parcela fixa de consumo','Fixed fuel-consumption term','Término fijo de consumo'),'L/h',.01)}{field('fuelSlope',T('Parcela proporcional de consumo','Load-dependent fuel term','Término proporcional de consumo'),'L/kWh',.01)}</div><p>{q('Curva de combustível hipotética: L/h = parcela fixa + parcela proporcional × kW. Substitua os coeficientes por dados do fabricante ao estudar um equipamento. SOC mínimo 20%, máximo 95% nos casos iniciais.','Hypothetical fuel curve: L/h = fixed term + proportional term × kW. Use manufacturer data when studying actual equipment. Initial cases use 20% minimum and 95% maximum SOC.','Curva hipotética: L/h = término fijo + término proporcional × kW. Usa datos del fabricante para equipos reales. Los casos iniciales usan SOC mínimo del 20% y máximo del 95%.')}</p></details></section>
 <section className="panel am-panel"><div className="panel-heading"><div><span className="eyebrow">{q('DESPACHO HORÁRIO','HOURLY DISPATCH','DESPACHO HORARIO')}</span><h2>{q('O que acontece em um dia?','What happens over a day?','¿Qué ocurre en un día?')}</h2></div><span className="small-tag">24 × 1 h</span></div><HybridChart r={r}/><div className="am-energy-totals"><span>Solar: <b>{n(r.pvKWh)} kWh</b></span><span>Diesel: <b>{n(r.dieselKWh)} kWh</b></span><span>{q('Solar aproveitada','Solar utilized','Solar aprovechada')}: <b>{n(r.solarUsedKWh)} kWh</b></span><span>{q('Perdas na bateria','Battery losses','Pérdidas de batería')}: <b>{n(r.storageLossKWh)} kWh</b></span></div><Note warning={r.unservedKWh>.001||r.socFinal<p.socStart-.5}><p>{r.unservedKWh>.001?q('Há energia não atendida. Revise recursos, limites de potência, combustível ou horários de uso.','Some demand is unserved. Review resources, power limits, fuel or usage schedules.','Hay energía no atendida. Revisa recursos, límites de potencia, combustible u horarios.'):q('Todas as cargas horárias foram atendidas neste cenário de um dia.','All hourly demand was served in this one-day scenario.','Toda la demanda horaria fue atendida en este escenario de un día.')}</p><p>{r.socFinal<p.socStart-.5?q('O SOC final ficou abaixo do inicial: repetir esse dia consome a reserva. Um dia atendido não comprova autonomia contínua.','Final SOC is below initial SOC: repeating this day consumes the reserve. One served day does not prove continuous autonomy.','El SOC final es inferior al inicial: repetir este día consume la reserva. Un día atendido no demuestra autonomía continua.'):q('Compare também sequências de dias, manutenção e logística antes de propor uma solução real.','Also assess sequences of days, maintenance and logistics before proposing a real solution.','Evalúa también secuencias de días, mantenimiento y logística antes de proponer una solución real.')}</p></Note></section></div><LoadEditor/>
 <details className="panel am-details"><summary>{q('Tabela horária e balanço','Hourly table and balance','Tabla horaria y balance')}</summary><div className="am-table-scroll"><table><thead><tr>{['h',q('Carga','Load','Carga'),'Solar','Diesel',q('Bateria → carga','Battery → load','Batería → carga'),'SOC %',q('Não atendida','Unserved','No atendida'),'L'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{r.rows.map(row=><tr key={row.hour}><td>{row.hour}</td><td>{n(row.load)}</td><td>{n(row.pv)}</td><td>{n(row.diesel)}</td><td>{n(row.batteryOut)}</td><td>{n(row.soc,1)}</td><td>{n(row.unserved)}</td><td>{n(row.fuel)}</td></tr>)}</tbody></table></div><p>{q('Energia por intervalo em kWh; como cada intervalo tem 1 h, o valor numérico coincide com a potência média em kW. SOC é dado ao fim da hora.','Energy per interval is in kWh; each interval is 1 h, so its numerical value matches mean power in kW. SOC is reported at hour end.','Energía por intervalo en kWh; cada intervalo tiene 1 h, por lo que coincide numéricamente con la potencia media en kW. El SOC corresponde al final de la hora.')}</p><Button icon="download" onClick={()=>Download('BioEnergia_Microrrede_24h.csv','\uFEFFhora;carga_kWh;solar_kWh;diesel_kWh;descarga_bateria_kWh;SOC_pct;nao_atendida_kWh;diesel_L\r\n'+r.rows.map(x=>[x.hour,x.load,x.pv,x.diesel,x.batteryOut,x.soc,x.unserved,x.fuel].map(v=>v.toFixed(5)).join(';')).join('\r\n'),'text/csv;charset=utf-8')}>{q('Exportar 24 horas em CSV','Export 24 hours as CSV','Exportar 24 horas en CSV')}</Button></details>
 <details className="panel am-details"><summary>{q('Fórmulas e alcance da simulação','Simulation formulas and scope','Fórmulas y alcance de la simulación')}</summary><div className="am-formulas"><code>Esolar = PkWp × HSP × fator global • perfil diurno normalizado entre 6 h e 18 h</code><code>ΔEbat = Ecarga × ηcarga − Edescarga / ηdescarga</code><code>Solar + Diesel + Descarga = Carga atendida + Carga da bateria + Excedentes</code></div><p>{q('Modelo energético de um dia, sem previsão meteorológica, rede trifásica, estabilidade, frequência dinâmica, química, partida de motores ou telemetria. O gerador fornece sua potência configurada; com pouco combustível, opera por uma fração da hora. A bateria e o inversor têm limites de potência. É um modelo virtual, não um gêmeo digital de uma instalação real.','One-day energy model without weather prediction, three-phase networks, stability, dynamic frequency, chemistry, motor starts or telemetry. With limited fuel the generator operates for part of an hour. Battery and inverter power limits apply. This is a virtual model, not a digital twin of an actual installation.','Modelo energético de un día sin pronóstico meteorológico, red trifásica, estabilidad, frecuencia dinámica, química, arranques ni telemetría. Con poco combustible el generador opera una fracción de la hora. Se aplican límites de potencia de batería e inversor. Es un modelo virtual, no un gemelo digital de una instalación real.')}</p></details></>;
}
const maintenanceItems=[
 ['water',T('Mapear chuva, alagamento, gotejamento e rotas de entrada de água.','Map rain, flooding, drips and water-entry paths.','Mapear lluvia, inundación, goteo y entrada de agua.')],
 ['heat',T('Prever ventilação, sombreamento técnico e limites térmicos das fichas.','Consider ventilation, appropriate shading and datasheet thermal limits.','Prever ventilación, sombreado técnico y límites térmicos de fichas.')],
 ['connections',T('Planejar inspeção de invólucros, conectores, cabos e sinais de corrosão.','Plan inspection of enclosures, connectors, cables and corrosion signs.','Planificar inspección de envolventes, conectores, cables y corrosión.')],
 ['logistics',T('Definir acesso, peças de reposição, transporte e comunicação com a comunidade.','Define access, spare parts, transport and community communication.','Definir acceso, repuestos, transporte y comunicación comunitaria.')],
 ['safety',T('Planejar desenergização, competência da equipe e consulta às normas aplicáveis.','Plan de-energization, team competence and applicable-standard review.','Planificar desenergización, competencia del equipo y consulta normativa.')]
] as const;
