function SingleLine(){const{q}=useLocale();return <svg className="am-single-line" viewBox="0 0 900 190" role="img" aria-label={q('Diagrama funcional de microrrede: solar e bateria via conversão CC/CA, diesel no barramento CA, cargas locais','Functional microgrid diagram: solar and battery via DC/AC conversion, diesel on AC bus, local loads','Diagrama funcional de microrred: solar y batería por conversión CC/CA, diésel en barra CA, cargas locales')}><g fill="none" stroke="currentColor" strokeWidth="2"><path d="M150 60H290 M150 135H290 M440 95H520V150H740 M650 55V150"/><rect x="15" y="35" width="135" height="50" rx="8"/><rect x="15" y="110" width="135" height="50" rx="8"/><rect x="290" y="58" width="150" height="75" rx="8"/><rect x="570" y="10" width="160" height="50" rx="8"/><rect x="740" y="125" width="145" height="50" rx="8"/></g><g fill="currentColor" textAnchor="middle" fontSize="15"><text x="82" y="66">Solar CC</text><text x="82" y="141">{q('Bateria','Battery','Batería')}</text><text x="365" y="92">CC / CA</text><text x="365" y="115">{q('Conversão','Conversion','Conversión')}</text><text x="650" y="41">Diesel CA</text><text x="812" y="155">{q('Cargas locais','Local loads','Cargas locales')}</text><text x="610" y="178" fontSize="12">{q('Barramento CA','AC bus','Barra CA')}</text></g></svg>;}
function GroundingDiagram(){const{q}=useLocale();return <details className="panel am-details"><summary>{q('Proteção e equipotencialização — esquema conceitual','Protection and bonding — conceptual diagram','Protección y equipotencialidad — esquema conceptual')}</summary><svg data-diagram="grounding" className="am-single-line" viewBox="0 0 900 215" role="img" aria-label={q('Massas dos equipamentos ligadas por PE ao barramento de equipotencialização, com ligação conceitual ao eletrodo. Neutro não representado.','Equipment exposed conductive parts connected by PE to the bonding bar and conceptually to the electrode. Neutral is not shown.','Masas de equipos conectadas por PE a barra de equipotencialidad y conceptualmente al electrodo. Neutro no representado.')}><g fill="none" stroke="currentColor" strokeWidth="2"><rect x="20" y="15" width="200" height="60" rx="8"/><rect x="300" y="15" width="200" height="60" rx="8"/><rect x="580" y="15" width="200" height="60" rx="8"/><path d="M120 75V120H680V75 M400 75V135 M540 160H805V185 M780 185H830 M788 194H822 M797 203H813"/><rect x="310" y="135" width="230" height="48" rx="8"/></g><g fill="currentColor" textAnchor="middle" fontSize="14"><text x="120" y="50">{q('Estruturas FV','PV frames','Estructuras FV')}</text><text x="400" y="50">{q('Carcaça do inversor','Inverter enclosure','Carcasa del inversor')}</text><text x="680" y="50">{q('Massas do quadro','Panel exposed parts','Masas del cuadro')}</text><text x="425" y="165">PE / BEP</text><text x="230" y="110" fontSize="12">PE</text><text x="760" y="150" fontSize="12">{q('Eletrodo','Electrode','Electrodo')}</text></g></svg><p>{q('A figura explica continuidade de proteção e equipotencialização. Não define esquema TT, TN ou IT, seção de PE, eletrodo, DPS ou dispositivo de proteção. O neutro não está representado: não se pode deduzir daqui uma ligação N–PE. Essas escolhas dependem das fontes, da instalação, de análise profissional e das normas aplicáveis.','This figure explains protective continuity and bonding. It does not define TT, TN or IT arrangements, PE section, electrode, surge protection or protective devices. Neutral is not shown: no N–PE bond can be inferred. These choices depend on sources, installation, professional analysis and applicable standards.','La figura explica continuidad de protección y equipotencialidad. No define esquema TT, TN o IT, sección PE, electrodo, DPS ni protección. El neutro no se representa: no se puede deducir una unión N–PE. Estas decisiones dependen de fuentes, instalación, análisis profesional y normas aplicables.')}</p></details>;}
function Projects(){const{q,t,n,lang}=useLocale(),{record,patch}=useLearning();const r=dispatchHybrid(record.hybrid,record.loads),bench=evaluateBench(record.bench,record.wires,record.fault);
 const rubric:[boolean,Localized][]=[[r.unservedKWh<=.001,T('Atender a demanda horária do caso','Serve the case’s hourly demand','Atender demanda horaria del caso')],[r.socFinal>=record.hybrid.socStart-.5,T('Encerrar com SOC próximo ou superior ao inicial','End with SOC near or above its initial value','Terminar con SOC cercano o superior al inicial')],[bench.connected&&!bench.tripped,T('Completar a topologia funcional da bancada','Complete the bench’s functional topology','Completar topología funcional del banco')],[bench.dropPct<=3,T('Atender à meta de queda CC de 3% do exercício','Meet the exercise’s 3% DC drop target','Cumplir meta de caída CC del 3% del ejercicio')],[record.maintenance.length>=5,T('Registrar o roteiro de manutenção e logística','Record maintenance and logistics checklist','Registrar mantenimiento y logística')],[record.projectNote.trim().length>=100,T('Registrar justificativa com pelo menos 100 caracteres','Record a rationale of at least 100 characters','Registrar justificación de al menos 100 caracteres')]];
 const report=()=>{const diagrams=Array.from(document.querySelectorAll('.am-single-line')).map(el=>el.outerHTML).join('');const content=`${diagrams}<p>${escapeHTML(q('Cenário fictício, análise didática e revisão docente obrigatória antes de qualquer aplicação real.','Fictional case, educational analysis; teacher review required before any real application.','Escenario ficticio, análisis didáctico; revisión docente requerida antes de aplicación real.'))}</p><h2>${escapeHTML(t(caseNames[record.caseId]))}</h2><p>Demanda: ${n(r.loadKWh)} kWh/dia · Diesel: ${n(r.dieselLiters)} L/dia · SOC: ${n(r.socInitial,1)}% → ${n(r.socFinal,1)}% · Energia não atendida: ${n(r.unservedKWh)} kWh</p><h2>${escapeHTML(q('Parâmetros declarados','Declared parameters','Parámetros declarados'))}</h2><pre>${escapeHTML(JSON.stringify({microrrede:record.hybrid,bancada:record.bench,cargas:record.loads},null,2))}</pre><h2>${escapeHTML(q('Critérios formativos','Formative criteria','Criterios formativos'))}</h2><ul>${rubric.map(([ok,label])=>`<li>${ok?'✓':'○'} ${escapeHTML(t(label))}</li>`).join('')}</ul><h2>${escapeHTML(q('Justificativa do estudante','Student rationale','Justificación del estudiante'))}</h2><pre>${escapeHTML(record.projectNote)}</pre><h2>${escapeHTML(q('Balanço de 24 horas','24-hour balance','Balance de 24 horas'))}</h2><table><tr><th>h</th><th>Carga kWh</th><th>Solar kWh</th><th>Diesel kWh</th><th>SOC %</th><th>Não atendida kWh</th></tr>${r.rows.map(x=>`<tr>${[x.hour,x.load,x.pv,x.diesel,x.soc,x.unserved].map(v=>`<td>${n(v)}</td>`).join('')}</tr>`).join('')}</table><h2>${escapeHTML(q('Referências para revisão','Review references','Referencias para revisión'))}</h2><ul>${lessons.flatMap(x=>x.references).filter((x,i,a)=>a.findIndex(r=>r.url===x.url)===i).map(x=>`<li>${escapeHTML(x.by)}: <a href="${escapeHTML(x.url)}">${escapeHTML(x.title)}</a></li>`).join('')}</ul><p>ΔV = 2ρLI/S. A meta de 3% é apenas do exercício; não representa limite normativo universal. O modelo não verifica ampacidade, aterramento, proteções ou arranque. Não comprova conformidade com ABNT NBR 5410, NR-10 ou regras da ANEEL.</p>`;Download('BioEnergia_Projeto_Amazonia.html',offlineDocument(q('Caderno de projeto — Amazônia','Project notebook — Amazon','Cuaderno de proyecto — Amazonía'),content,lang),'text/html;charset=utf-8');};
 return <><div className="am-project-intro"><span className="eyebrow">{q('APRENDER RESOLVENDO UM PROBLEMA','LEARN BY SOLVING A PROBLEM','APRENDER RESOLVIENDO UN PROBLEMA')}</span><h2>{q('Energia para uma escola ribeirinha.','Energy for a riverside school.','Energía para una escuela ribereña.')}</h2><p>{q('Uma escola fictícia com 30 estudantes precisa de iluminação, ventilação, informática, refrigeração e água. Investigue um dia normal, um dia pouco ensolarado e a logística de combustível. Os dados são hipóteses para a aprendizagem.','A fictional school with 30 students needs lighting, ventilation, computers, refrigeration and water. Investigate a normal day, a low-sun day and fuel logistics. Data are learning assumptions.','Una escuela ficticia con 30 alumnos necesita iluminación, ventilación, informática, refrigeración y agua. Investiga un día normal, un día de poco sol y la logística de combustible. Los datos son hipótesis educativas.')}</p></div><section className="panel am-panel"><div className="panel-heading"><h2>{q('Diagrama funcional para discussão','Functional diagram for discussion','Diagrama funcional para discusión')}</h2><span className="small-tag">{q('Sem escala','Not to scale','Sin escala')}</span></div><SingleLine/><Note><p>{q('A linha única representa o fluxo funcional, não um unifilar executivo. O projeto real deve especificar proteção, seccionamento, aterramento, equipotencialização, condutores e os limites dos equipamentos conforme análise técnica e normas aplicáveis.','The single line represents functional flow, not a construction single-line diagram. Actual design must specify protection, isolation, grounding, bonding, conductors and equipment limits through engineering analysis and applicable standards.','La línea representa el flujo funcional, no un unifilar ejecutivo. El diseño real debe especificar protecciones, seccionamiento, puesta a tierra, equipotencialidad, conductores y límites según análisis técnico y normas aplicables.')}</p></Note></section><GroundingDiagram/>
 <div className="am-two-col"><section className="panel am-panel"><div className="panel-heading"><h2>{q('Critérios de investigação','Investigation criteria','Criterios de investigación')}</h2><span className="am-score">{rubric.filter(([ok])=>ok).length}/6</span></div><ul className="am-rubric">{rubric.map(([ok,label],i)=><li key={i} className={ok?'good':''}><Icon name={ok?'check':'target'}/><span>{t(label)}</span></li>)}</ul><p className="am-caption">{q('Feedback formativo automático. A presença de texto não avalia a qualidade da justificativa; o docente deve revisar evidências, decisões, segurança e adequação local. Não emite certificação.','Automatic formative feedback. Text presence does not assess rationale quality; a teacher must review evidence, decisions, safety and local suitability. No certification is issued.','Retroalimentación formativa automática. La presencia de texto no evalúa su calidad; un docente debe revisar evidencias, decisiones, seguridad y adecuación local. No emite certificación.')}</p></section><section className="panel am-panel"><h2>{q('Manutenção no contexto amazônico','Maintenance in the Amazon context','Mantenimiento en contexto amazónico')}</h2><div className="am-checklist">{maintenanceItems.map(([id,label])=><label key={id}><input type="checkbox" checked={record.maintenance.includes(id)} onChange={e=>patch({maintenance:e.target.checked?[...record.maintenance,id]:record.maintenance.filter(x=>x!==id)})}/><span>{t(label)}</span></label>)}</div><p className="am-caption">{q('Umidade do interior amazônico não equivale a maresia. Avalie exposição salina somente quando existir influência costeira ou outra fonte comprovada de contaminantes.','Inland Amazon humidity is not the same as salt spray. Assess salinity only with actual coastal influence or another evidenced contaminant source.','La humedad amazónica interior no equivale a salitre. Evalúa salinidad solo con influencia costera real u otra fuente comprobada de contaminantes.')}</p></section></div><section className="panel am-panel"><label className="am-notes-label" htmlFor="amazon-project-note">{q('Justifique suas decisões','Explain your decisions','Justifica tus decisiones')}</label><p>{q('Registre fonte dos dados, mês de referência solar, horários, limites, SOC inicial/final, combustível, manutenção e limitações. Explique quais medições de campo ainda faltam.','Record data sources, solar-reference month, schedules, limits, initial/final SOC, fuel, maintenance and limitations. Explain which field measurements are still needed.','Registra fuentes de datos, mes solar, horarios, límites, SOC inicial/final, combustible, mantenimiento y limitaciones. Explica qué mediciones de campo faltan.')}</p><textarea id="amazon-project-note" value={record.projectNote} onChange={e=>patch({projectNote:e.target.value})} maxLength={15000} placeholder={q('Minha hipótese e minhas evidências…','My assumption and evidence…','Mi hipótesis y mis evidencias…')}/><div className="am-actions"><Button icon="download" kind="primary" onClick={report}>{q('Baixar relatório do projeto','Download project report','Descargar informe del proyecto')}</Button><Button icon="print" onClick={()=>window.print()}>{q('Imprimir / PDF','Print / PDF','Imprimir / PDF')}</Button></div></section></>;
}
function Study(){const{q,t,lang}=useLocale(),learning=useLearning(),{record,patch}=learning;const[selected,setSelected]=useState(0),input=useRef<HTMLInputElement>(null),[message,setMessage]=useState('');const lesson=lessons[selected];
 const makeGuide=(all:boolean)=>Download(all?'BioEnergia_Apostila_Amazonia.html':'BioEnergia_Modulo_Amazonia.html',studyGuide(all?lessons:[lesson],lang,SENAI_HUB_LOGO,all),'text/html;charset=utf-8');
 const standalone=async()=>{if(document.documentElement.dataset.distribution==='modular'){try{const response=await fetch('./plataforma-portatil.html');if(!response.ok)throw new Error('HTML');Download('BioEnergia_Amazonia_Offline.html',await response.text(),'text/html;charset=utf-8');}catch{setMessage(q('Não foi possível obter o HTML portátil. Use o pacote original ou tente novamente.','Unable to get portable HTML. Use the original package or retry.','No se pudo obtener el HTML portátil. Usa el paquete original o vuelve a intentar.'));}return;}const clone=document.documentElement.cloneNode(true) as HTMLElement;clone.querySelector('#root')?.replaceChildren();clone.querySelector('base')?.remove();clone.querySelector('link[rel=manifest]')?.remove();Download('BioEnergia_Amazonia_Offline.html','<!doctype html>'+clone.outerHTML,'text/html;charset=utf-8');};
 return <><div className="am-offline-status"><Icon name={learning.offlineReady?'check':'download'}/><div><strong>{learning.offlineReady?q('Conteúdo preparado para este dispositivo','Content ready on this device','Contenido preparado en este dispositivo'):q('Leve o laboratório com você.','Take the laboratory with you.','Lleva el laboratorio contigo.')}</strong><p>{q('Textos, imagens e modelos estão incluídos. Referências externas exigem internet. Exporte seu caderno para transferir o trabalho a outro dispositivo.','Texts, images and models are included. External references need internet. Export your notebook to transfer work to another device.','Textos, imágenes y modelos están incluidos. Las referencias externas requieren internet. Exporta tu cuaderno para transferir el trabajo a otro dispositivo.')}</p></div></div>
 <section className="panel am-panel">{location.protocol!=='file:'&&<p><a className="am-guide-link" href="./apostila-amazonia.html" target="_blank" rel="noopener noreferrer">{q('Ler apostila completa em português (versão leve)','Read the full Portuguese guide (light version)','Leer guía completa en portugués (versión ligera)')}<Icon name="external"/></a></p>}<div className="am-actions"><Button kind="primary" icon="download" onClick={standalone}>{q('Baixar plataforma HTML offline','Download offline HTML platform','Descargar plataforma HTML sin conexión')}</Button><Button icon="save" onClick={()=>void learning.prepareOffline()}>{q('Preparar acesso offline no navegador','Prepare browser offline access','Preparar acceso sin conexión en navegador')}</Button>{learning.canInstall&&<Button icon="globe" onClick={()=>void learning.install()}>{q('Instalar aplicativo','Install app','Instalar aplicación')}</Button>}<Button icon="book" onClick={()=>makeGuide(true)}>{q('Baixar apostila completa','Download full study guide','Descargar guía completa')}</Button></div>{learning.offlineMessage&&<p role="status">{learning.offlineMessage==='https'?q('A instalação offline no navegador precisa de HTTPS ou localhost. O HTML baixado já funciona sem rede.','Browser offline installation needs HTTPS or localhost. Downloaded HTML already works without a network.','La instalación sin conexión requiere HTTPS o localhost. El HTML descargado funciona sin red.'):learning.offlineMessage==='retry'?q('Não foi possível confirmar o cache. Mantenha a cópia HTML e tente novamente com conexão.','Offline cache could not be confirmed. Keep the HTML copy and retry with a connection.','No se pudo confirmar la caché. Conserva el HTML y vuelve a intentarlo con conexión.'):q('Conteúdo offline confirmado para este dispositivo.','Offline content confirmed for this device.','Contenido sin conexión confirmado en este dispositivo.')}</p>}</section>
 <div className="am-study-layout"><aside className="panel am-study-list">{lessons.map((item,i)=><button key={item.id} className={selected===i?'selected':''} onClick={()=>setSelected(i)}><span>{String(i+1).padStart(2,'0')}</span><strong>{t(item.title)}</strong>{record.completed.includes(item.id)&&<Icon name="check"/>}</button>)}</aside><article className="panel am-panel am-lesson"><span className="eyebrow">{q('MÓDULO DE ESTUDO','STUDY MODULE','MÓDULO DE ESTUDIO')} {selected+1}/5</span><h2>{t(lesson.title)}</h2><p>{t(lesson.summary)}</p><h3>{q('Ao concluir, você deverá…','After completing, you should…','Al completar, deberás…')}</h3><ul>{lesson.objectives.map((item,i)=><li key={i}>{t(item)}</li>)}</ul>{lesson.sections.map((section,i)=><section key={i}><h3>{t(section.title)}</h3><p>{t(section.body)}</p></section>)}<div className="am-learning-task"><strong>{q('Investigue e registre','Investigate and record','Investiga y registra')}</strong><p>{t(lesson.activity)}</p></div><div className="reference-links">{lesson.references.map(ref=><a href={ref.url} target="_blank" rel="noopener noreferrer" key={ref.url} title={ref.title}>{ref.by}<Icon name="external"/></a>)}</div><div className="am-actions"><Button icon="check" kind="primary" onClick={()=>patch({completed:record.completed.includes(lesson.id)?record.completed.filter(id=>id!==lesson.id):[...record.completed,lesson.id]})}>{record.completed.includes(lesson.id)?q('Concluído • desmarcar','Completed • unmark','Completado • desmarcar'):q('Marcar estudo concluído','Mark study completed','Marcar estudio completado')}</Button><Button icon="download" onClick={()=>makeGuide(false)}>{q('Baixar este módulo','Download this module','Descargar este módulo')}</Button></div></article></div>
 <section className="panel am-panel"><div className="panel-heading"><h2>{q('Seu caderno portátil','Your portable notebook','Tu cuaderno portátil')}</h2><span className="small-tag">JSON</span></div><p>{q('O backup leva parâmetros, conexões, cargas, registros, perguntas e progresso. Não inclui credenciais da turma. Guarde uma cópia: limpeza do navegador ou falta de espaço pode apagar dados locais.','The backup includes parameters, connections, loads, notes, questions and progress. It excludes class credentials. Keep a copy: clearing browser data or low storage can remove local data.','La copia incluye parámetros, conexiones, cargas, notas, preguntas y progreso. Excluye credenciales de clase. Guarda una copia: limpiar el navegador o la falta de espacio puede borrar datos locales.')}</p><div className="am-actions"><Button icon="download" onClick={()=>Download('BioEnergia_Caderno_Amazonia.json',learning.backup(),'application/json')}>{q('Exportar caderno','Export notebook','Exportar cuaderno')}</Button><Button icon="save" onClick={()=>input.current?.click()}>{q('Importar caderno','Import notebook','Importar cuaderno')}</Button><input ref={input} type="file" accept=".json,application/json" hidden onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>550000)throw new Error('size');learning.importBackup(await file.text());setMessage(q('Caderno importado e salvo neste dispositivo.','Notebook imported and saved on this device.','Cuaderno importado y guardado en este dispositivo.'));}catch{setMessage(q('Arquivo incompatível. Use um backup JSON exportado por esta plataforma.','Incompatible file. Use a JSON backup exported by this platform.','Archivo incompatible. Usa una copia JSON exportada por esta plataforma.'));}e.target.value='';}}/></div>{message&&<p role="status">{message}</p>}</section></>;
}
function Tutoring(){const{q,t}=useLocale(),learning=useLearning(),{record}=learning;const[alias,setAlias]=useState(''),[code,setCode]=useState(''),[teacher,setTeacher]=useState(false),[key,setKey]=useState(''),[subject,setSubject]=useState(''),[question,setQuestion]=useState(''),[message,setMessage]=useState(''),[reply,setReply]=useState<Record<string,string>>({});
 const run=async(work:()=>Promise<void>)=>{try{await work();setMessage(q('Atualizado.','Updated.','Actualizado.'));}catch(e){setMessage(e instanceof Error&&e.message==='AUTH'?q('Entre novamente na turma.','Sign in to the class again.','Vuelve a entrar en la clase.'):q('Não foi possível concluir. Verifique conexão e código da turma. Seus registros locais foram preservados.','Could not complete. Check connection and class code. Local records are preserved.','No se pudo completar. Comprueba conexión y código de clase. Los registros locales se conservaron.'));}};
 return <><Note><p>{q('A tutoria troca mensagens de texto com o servidor da turma. Na cópia HTML local, as perguntas ficam no caderno até você abrir o servidor configurado pelo docente e importar seu backup. Com uma sessão de estudante ativa, alterações são sincronizadas quando a página está aberta e a conexão retorna.','Tutoring exchanges text with the class server. In a local HTML copy, questions stay in your notebook until you open the teacher-configured server and import your backup. With an active student session, changes sync when the page is open and connectivity returns.','La tutoría intercambia texto con el servidor de clase. En la copia HTML local, las preguntas quedan en el cuaderno hasta abrir el servidor configurado por el docente e importar la copia. Con sesión de estudiante activa, los cambios se sincronizan con la página abierta al recuperar conexión.')}</p></Note>
 <div className="am-two-col"><section className="panel am-panel"><h2>{q('Conectar à turma','Connect to class','Conectar a la clase')}</h2><p className="am-server-state"><span className={`status-dot ${learning.serverEnabled?'':'muted'}`}/>{learning.serverEnabled?q('Servidor da turma disponível nesta versão','Class server is available in this version','Servidor de clase disponible en esta versión'):q('Modo local • servidor da turma não configurado nesta versão','Local mode • class server is not configured in this version','Modo local • servidor de clase no configurado en esta versión')}</p>{!learning.session?<form className="am-login" onSubmit={e=>{e.preventDefault();void run(()=>learning.login(alias,code,teacher?key:undefined));}}><label>{q('Apelido para a turma','Class nickname','Apodo para la clase')}<input value={alias} onChange={e=>setAlias(e.target.value)} minLength={2} maxLength={40} required autoComplete="nickname"/></label><label>{q('Código da turma','Class code','Código de la clase')}<input value={code} type="password" onChange={e=>setCode(e.target.value)} required autoComplete="off"/></label><label className="am-checkbox"><input type="checkbox" checked={teacher} onChange={e=>setTeacher(e.target.checked)}/>{q('Acesso de docente','Teacher access','Acceso docente')}</label>{teacher&&<label>{q('Chave do docente','Teacher key','Clave docente')}<input type="password" value={key} onChange={e=>setKey(e.target.value)} required autoComplete="off"/></label>}<Button type="submit" icon="shield" disabled={!learning.serverEnabled||!learning.isOnline}>{q('Entrar na turma','Join class','Entrar en la clase')}</Button></form>:<><p>{learning.session.role==='teacher'?q('Sessão de docente. Respostas ficam identificadas como feedback docente.','Teacher session. Replies are identified as teacher feedback.','Sesión docente. Las respuestas se identifican como retroalimentación docente.'):q('Sessão de estudante ativa. Seu caderno é privado; as perguntas são compartilhadas com a turma.','Student session active. Your notebook is private; questions are shared with the class.','Sesión de estudiante activa. Tu cuaderno es privado; las preguntas se comparten con la clase.')}</p><div className="am-actions"><Button icon="reset" onClick={()=>void run(learning.refreshForum)}>{q('Atualizar mensagens','Refresh messages','Actualizar mensajes')}</Button>{learning.session.role==='student'&&<Button icon="save" onClick={()=>void learning.sync()}>{q('Sincronizar agora','Sync now','Sincronizar ahora')}</Button>}<Button icon="close" onClick={learning.logout}>{q('Sair','Sign out','Salir')}</Button></div></>}</section>
 <section className="panel am-panel"><h2>{q('Pergunta para a tutoria','Question for tutoring','Pregunta para tutoría')}</h2><form className="am-login" onSubmit={e=>{e.preventDefault();learning.ask({subject:subject.trim(),body:question.trim(),module:record.caseId});setSubject('');setQuestion('');setMessage(q('Pergunta guardada no caderno. O envio depende de uma sessão de estudante conectada ao servidor da turma.','Question saved in the notebook. Sending requires a student session connected to the class server.','Pregunta guardada en el cuaderno. El envío requiere sesión de estudiante conectada al servidor de clase.'));}}><label>{q('Assunto','Subject','Asunto')}<input value={subject} onChange={e=>setSubject(e.target.value)} required minLength={3} maxLength={120}/></label><label>{q('Sua dúvida e os dados do ensaio','Question and experiment data','Duda y datos del ensayo')}<textarea value={question} onChange={e=>setQuestion(e.target.value)} required minLength={10} maxLength={3000} placeholder={q('Descreva parâmetros, leitura obtida, expectativa e o que já investigou.','Describe parameters, observed reading, expectation and what you investigated.','Describe parámetros, lectura obtenida, expectativa y lo investigado.')}/></label><Button type="submit" icon="chat">{q('Guardar pergunta no caderno','Save question to notebook','Guardar pregunta en cuaderno')}</Button></form></section></div>{message&&<p className="am-message" role="status">{message}</p>}
 {!!learning.learners.length&&<section className="panel am-panel"><h2>{q('Acompanhamento docente','Teacher overview','Seguimiento docente')}</h2><div className="am-table-scroll"><table><thead><tr><th>{q('Apelido','Nickname','Apodo')}</th><th>{q('Módulos','Modules','Módulos')}</th><th>{q('Última sincronização','Last sync','Última sincronización')}</th><th>{q('Registro de projeto','Project rationale','Registro de proyecto')}</th></tr></thead><tbody>{learning.learners.map(s=><tr key={s.id}><td>{s.alias}</td><td>{s.completed}/5</td><td>{s.updatedAt?new Date(s.updatedAt).toLocaleString():'—'}</td><td>{s.projectNote?q('Registrado','Recorded','Registrado'):q('Pendente','Pending','Pendiente')}</td></tr>)}</tbody></table></div></section>}
 <div className="am-two-col"><section className="panel am-panel"><h2>{q('Perguntas deste dispositivo','Questions on this device','Preguntas de este dispositivo')}</h2>{record.questions.length?record.questions.slice().reverse().map(item=><article className="am-thread" key={item.id}><strong>{item.subject}</strong><p>{item.body}</p><small>{learning.threads.some(t=>t.id===item.id)?q('Disponível no mural carregado','Available in the loaded discussion','Disponible en el muro cargado'):q('Preservada no caderno • consulte o mural da turma','Preserved in notebook • check the class discussion','Conservada en cuaderno • consulta el muro de clase')}</small></article>):<p>{q('Registre uma dúvida com as evidências do seu experimento.','Record a question with evidence from your experiment.','Registra una duda con evidencias de tu experimento.')}</p>}</section><section className="panel am-panel"><h2>{q('Mural da turma','Class discussion','Muro de clase')}</h2>{learning.threads.length?learning.threads.map(thread=><article className="am-thread" key={thread.id}><small>{thread.alias} · {q('Estudante','Student','Estudiante')}</small><h3>{thread.subject}</h3><p>{thread.body}</p>{thread.replies.map(response=><blockquote key={response.id}><small>{response.alias} · {q('Docente','Teacher','Docente')}</small><p>{response.body}</p></blockquote>)}{learning.session?.role==='teacher'&&<form onSubmit={e=>{e.preventDefault();void run(async()=>{await learning.reply(thread.id,reply[thread.id]??'');setReply(p=>({...p,[thread.id]:''}));});}}><label className="sr-only" htmlFor={'reply-'+thread.id}>{q('Feedback docente','Teacher feedback','Retroalimentación docente')}</label><textarea id={'reply-'+thread.id} value={reply[thread.id]??''} onChange={e=>setReply(p=>({...p,[thread.id]:e.target.value}))} minLength={3} maxLength={3000} required/><Button type="submit" icon="chat">{q('Publicar feedback docente','Post teacher feedback','Publicar retroalimentación docente')}</Button></form>}</article>):<p>{q('Conecte-se ao servidor da turma para consultar perguntas e respostas. Nenhum envio é realizado por e-mail ou serviços externos.','Connect to the class server to view questions and replies. No email or external messaging service is used.','Conéctate al servidor de clase para consultar preguntas y respuestas. No se usa correo ni mensajería externa.')}</p>}</section></div></>;
}
export function AmazonEntry(){const{q}=useLocale(),{navigate}=useApp();return <section className="am-entry panel"><div><span className="eyebrow">{q('CAMPUS AMAZÔNIA','AMAZON CAMPUS','CAMPUS AMAZONÍA')}</span><h2>{q('Da bancada virtual à comunidade.','From the virtual bench to the community.','Del banco virtual a la comunidad.')}</h2><p>{q('Conecte componentes, investigue falhas e planeje uma microrrede solar–bateria–diesel para um caso amazônico. Leve o caderno e a apostila para estudar offline.','Connect components, investigate faults and plan a solar–battery–diesel microgrid for an Amazon case. Take your notebook and study guide offline.','Conecta componentes, investiga fallos y planifica una microrred solar–batería–diésel para un caso amazónico. Lleva cuaderno y guía sin conexión.')}</p></div><Button kind="primary" icon="arrow" onClick={()=>navigate('amazon')}>{q('Abrir Campus Amazônia','Open Amazon Campus','Abrir Campus Amazonía')}</Button></section>;}
export default function AmazonCampus(){const{q,t}=useLocale(),learning=useLearning();const[tab,setTab]=useState<CampusTab>('bench');const pending=learning.session?.role!=='teacher'&&learning.record.sequence>learning.ack;const storageLabel={loading:q('Abrindo caderno…','Opening notebook…','Abriendo cuaderno…'),indexeddb:q('Salvo neste dispositivo','Saved on this device','Guardado en este dispositivo'),local:q('Salvo neste navegador','Saved in this browser','Guardado en este navegador'),memory:q('Somente nesta sessão • exporte o caderno','This session only • export the notebook','Solo esta sesión • exporta el cuaderno')};
 return <div className="am-campus"><Heading eyebrow={T('EDUCAÇÃO PROFISSIONAL • CONTEXTO AMAZÔNICO','VOCATIONAL EDUCATION • AMAZON CONTEXT','EDUCACIÓN PROFESIONAL • CONTEXTO AMAZÓNICO')} title={T('Energia para aprender. Autonomia para transformar.','Energy to learn. Autonomy to transform.','Energía para aprender. Autonomía para transformar.')} description={T('Bancadas, casos de comunidades isoladas e materiais para estudar onde a conexão não chega. Experimente com hipóteses claras e evidências rastreáveis.','Virtual benches, isolated-community cases and materials to study where connectivity does not reach. Experiment with clear assumptions and traceable evidence.','Bancos virtuales, casos de comunidades aisladas y materiales para estudiar donde no llega la conexión. Experimenta con hipótesis claras y evidencias verificables.')}/><div className="am-campus-status"><span><Icon name="save"/>{learning.storage!=='loading'&&learning.storage!=='memory'&&learning.lastSaved!==learning.record.updatedAt?q('Salvando no dispositivo…','Saving on device…','Guardando en dispositivo…'):storageLabel[learning.storage]}</span><span><Icon name="book"/>{learning.record.completed.length}/5 {q('módulos estudados','modules studied','módulos estudiados')}</span><span><span className={`status-dot ${learning.session&&!pending?'':'muted'}`}/>{learning.syncStatus==='sending'?q('Sincronizando…','Syncing…','Sincronizando…'):learning.syncStatus==='error'?q('Envio pendente • cópia local mantida','Sync pending • local copy retained','Envío pendiente • copia local conservada'):learning.syncStatus==='login'?q('Sessão expirada • entre novamente','Session expired • sign in again','Sesión caducada • vuelve a entrar'):learning.session?pending?q('Alterações aguardando envio','Changes awaiting sync','Cambios pendientes de envío'):q('Sincronizado com a turma','Synced with class','Sincronizado con clase'):q('Estudo local • sem sincronização de turma','Local study • no class sync','Estudio local • sin sincronización de clase')}</span></div><div className="am-tabs" role="tablist" aria-label={q('Ambientes do Campus Amazônia','Amazon Campus environments','Entornos del Campus Amazonía')}>{tabs.map((id,i)=><button key={id} role="tab" id={'am-tab-'+id} aria-controls={'am-panel-'+id} aria-selected={tab===id} tabIndex={tab===id?0:-1} onKeyDown={e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setTab(tabs[next]);document.getElementById('am-tab-'+tabs[next])?.focus();}}} onClick={()=>setTab(id)}><Icon name={['flask','bolt','target','book','chat'][i]}/>{t(tabNames[id])}</button>)}</div><section role="tabpanel" id={'am-panel-'+tab} aria-labelledby={'am-tab-'+tab}>{tab==='bench'?<Bench/>:tab==='microgrid'?<Microgrid/>:tab==='projects'?<Projects/>:tab==='study'?<Study/>:<Tutoring/>}</section></div>;
}
